def Erdos902.Core.paley7Digraph : Digraph (Fin 7) :=
  Digraph.mk fun u v =>
  have d := HMod.hMod (HSub.hSub (HAdd.hAdd (↑v) 7) ↑u) 7;
  Or (Eq d 1) (Or (Eq d 2) (Eq d 4))

def Erdos902.Core.IsTournament.{u_1} {V : Type u_1} (G : Digraph V) : Prop :=
  fun {V} G =>
  And (∀ (v : V), Not (Digraph.Adj G v v)) (∀ (u v : V), Ne u v → Iff (Digraph.Adj G u v) (Not (Digraph.Adj G v u)))
